        "landing.slider.example1.question": "¡Hola! ¿Cuál es su horario de sábado y cuánto cuesta un corte de pelo para mujer?",
        "landing.slider.example1.reply": "Los sábados abrimos de 9:00 a 16:00.\nUn corte de pelo para mujer cuesta 35$, incluye lavado y secado.\nLos sábados por la tarde se llenan rápido, así que conviene reservar pronto.",
        "landing.slider.example2.question": "¿Hacen blanqueamiento dental? ¿Puedo ir sin cita o necesito pedir turno?",
        "landing.slider.example2.reply": "El blanqueamiento dental cuesta 120$.\nSiempre lo reservamos con antelación para asegurar suficiente tiempo, aunque para una revisión rápida sí aceptamos sin cita.\nTengo un hueco libre el jueves a las 14:00, ¿te viene bien?",
        "landing.slider.example3.question": "Se me rompió la pantalla del iPhone 13, ¿cuánto cuesta arreglarla y cuánto tarda?",
        "landing.slider.example3.reply": "El cambio de pantalla del iPhone 13 cuesta 89$, con 6 meses de garantía en la pieza.\nSuele estar listo el mismo día si lo traes antes de las 14:00.\nSi el marco también está doblado, lo revisamos aparte primero para que no haya sorpresas en el precio.",
        "landing.slider.example4.question": "Se me gotea el grifo de la cocina, ¿puede venir alguien a revisarlo esta semana?",
        "landing.slider.example4.reply": "¡Lo siento mucho!\nTenemos disponibilidad el miércoles y jueves por la tarde — la visita más inspección cuesta 25$.\nSi necesita una junta o cartucho nuevo, te lo presupuestamos aparte antes de tocar nada.",
        "landing.slider.example5.question": "¿A qué hora es el check-in y se permiten mascotas?",
        "landing.slider.example5.reply": "El check-in es a partir de las 15:00 y el check-out hasta las 11:00.\nLas mascotas son bienvenidas — se aplica una pequeña tarifa de limpieza.\nSi nos avisas con antelación, dejaremos toallas extra para ellas.",
        "landing.slider.example6.question": "¿Cuánto cuesta una llamada de estrategia de una hora y cómo puedo reservarla?",
        "landing.slider.example6.reply": "Una llamada de estrategia de una hora cuesta 90$ e incluye un breve resumen escrito después.\nTengo un hueco libre el martes o jueves por la mañana esta semana, ¿te viene bien alguno?",
        "landing.slider.example7.question": "¿El vestido midi verde viene en talla M? ¿Cuál es su política de devoluciones?",
        "landing.slider.example7.reply": "¡Sí, el vestido midi verde sigue disponible en talla M!\nLas devoluciones son gratuitas dentro de 14 días si la etiqueta sigue puesta.\nEso sí, las piezas alteradas no tienen devolución.",
        "landing.slider.example8.question": "¿Cuánto cuesta una manicura semipermanente y hay que reservar con antelación?",
        "landing.slider.example8.reply": "Una manicura semipermanente cuesta 28$ y dura unos 45 minutos.\nLos fines de semana se llenan un par de días antes, pero entre semana normalmente podemos atenderte el mismo día.",
        "landing.slider.example9.question": "¿Cuánto cuesta el plan mensual y está bien si nunca he entrenado antes?",
        "landing.slider.example9.reply": "El plan mensual cuesta 80$ por 8 sesiones.\nY sí — muchos de nuestros socios empiezan desde cero.\nTu primera sesión es una valoración suave para que el entrenador arme un plan según tu nivel real.",
        "landing.slider.example10.question": "¿Tienen disponibilidad para una boda el 12 de septiembre y qué incluye su paquete?",
        "landing.slider.example10.reply": "¡El 12 de septiembre sigue libre!\nEl paquete estándar incluye 6 horas de cobertura y más de 300 fotos editadas.\nMás una galería de adelanto la misma semana para que no tengas que esperar meses para ver algo.",

