        "landing.slider.time.now": "Upravo sada",
        "landing.slider.time.m2": "Pre 2 min",
        "landing.slider.time.m5": "Pre 5 min",
        "landing.slider.time.m12": "Pre 12 min",
        "landing.slider.time.h1": "Pre 1 č",

        "landing.slider.example1.question": "Ćao! Koje je radno vreme subotom, i koliko košta žensko šišanje?",
        "landing.slider.example1.reply": "Subotom radimo od 9:00 do 16:00.\nŽensko šišanje košta 35$, uključuje pranje i feniranje.\nSubotom popodne brzo se popuni, pa je bolje zakazati na vreme.",
        "landing.slider.example2.question": "Da li radite izbleđivanje zuba? Mogu li samo da svratim ili moram da zakažem termin?",
        "landing.slider.example2.reply": "Izbeljivanje zuba košta 120$.\nZa to uvek zakazujemo unapred kako bismo obezbedili dovoljno vremena, dok za brzi pregled možete doći i bez zakazivanja.\nImam slobodan termin u četvrtak u 14:00, da li vam odgovara?",
        "landing.slider.example3.question": "Pukao mi je ekran na iPhone 13 — koliko košta popravka i koliko traje?",
        "landing.slider.example3.reply": "Zamena ekrana za iPhone 13 košta 89$ sa 6 meseci garancije na deo.\nObično gotovo istog dana ako donesete pre 14:00.\nAko je i ram savijen, to prvo posebno proveravamo da ne bi bilo iznenađenja u ceni.",
        "landing.slider.example4.question": "Kurim mi slavina u kuhinji — da li neko može da svrati da pogleda ove nedelje?",
        "landing.slider.example4.reply": "Žao mi je!\nImamo slobodno sredu i četvrtak posle podne — izlazak sa pregledom košta 25$.\nAko zatreba nova zaptivka ili kertridž, to ćemo posebno da vam iznesemo pre nego što bilo šta dirnemo.",
        "landing.slider.example5.question": "U koliko sati je check-in, i da li su kućni ljubimci dozvoljeni?",
        "landing.slider.example5.reply": "Check-in je od 15:00, check-out do 11:00.\nKućni ljubimci su dobrodošli — naplaćuje se mala naknada za čišćenje.\nAko nam javite unapred, ostavićemo im dodatne peškire.",
        "landing.slider.example6.question": "Koliko košta jednosatni strateški poziv, i kako mogu da zakažem?",
        "landing.slider.example6.reply": "Jednosatni strateški poziv košta 90$ i uključuje kratak pisani rezime nakon toga.\nImam slobodan termin utorkom ili četvrtkom ujutru ove nedelje, da li vam neki od njih odgovara?",
        "landing.slider.example7.question": "Da li zelena midi haljina dolazi u veličini M, i kakva vam je politika povraćaja?",
        "landing.slider.example7.reply": "Da, zelena midi haljina je još na stanju u veličini M!\nPovraćaj je besplatan u roku od 14 dana ako je etiketa i dalje pričvršćena.\nS tim što prepravljeni komadi ne podležu povraćaju.",
        "landing.slider.example8.question": "Koliko košta gel manikir, i da li treba da zakažem unapred?",
        "landing.slider.example8.reply": "Gel manikir košta 28$ i traje oko 45 minuta.\nVikendom se popuni par dana unapred, ali radnim danima obično možemo da vas ubacimo isti dan.",
        "landing.slider.example9.question": "Kolika je cena mesečnog paketa, i da li je u redu ako nikad ranije nisam trenirao/la?",
        "landing.slider.example9.reply": "Mesečni paket košta 80$ za 8 termina.\nI da — mnogi naši članovi kreću od nule.\nPrvi termin je blaga procena kako bi trener napravio plan prilagođen vašem stvarnom nivou.",
        "landing.slider.example10.question": "Da li imate slobodan termin za venčanje 12. septembra, i šta uključuje vaš paket?",
        "landing.slider.example10.reply": "12. septembar je još uvek slobodan!\nStandardni paket uključuje 6 sati snimanja i preko 300 obrađenih fotografija.\nPlus galeriju sa najavom fotografija iste nedelje, tako da ne čekate mesecima da vidite bilo šta.",

