        "landing.slider.example1.question": "你好!请问周六营业时间是几点,女士理发多少钱?",
        "landing.slider.example1.reply": "我们周六9点到16点营业。\n女士理发是35欧元,包含洗发和吹干。\n周六下午名额很快就满,建议尽快预约。",
        "landing.slider.example2.question": "你们提供牙齿美白服务吗?可以直接过来还是需要预约?",
        "landing.slider.example2.reply": "牙齿美白是120欧元。\n这项服务我们都会提前预约以留出足够时间,不过简单检查可以直接来。\n周四下午2点还有空档,方便吗?",
        "landing.slider.example3.question": "我的iPhone 13屏幕碎了,维修要多少钱,需要多长时间?",
        "landing.slider.example3.reply": "iPhone 13换屏是89欧元,配件享6个月保修。\n如果下午2点前送来通常当天就能修好。\n如果边框也有变形,我们会先单独检查,以免价格上有意外。",
        "landing.slider.example4.question": "我家厨房的水龙头漏水了,这周能有人过来看看吗?",
        "landing.slider.example4.reply": "很抱歉听到这个消息!\n我们周三和周四下午有空,上门检查费是25欧元。\n如果需要更换密封圈或阀芯,会在动手前单独报价。",
        "landing.slider.example5.question": "请问几点可以入住,可以带宠物吗?",
        "landing.slider.example5.reply": "入住时间为15:00起,退房时间为11:00前。\n可以带宠物,需收取少量清洁费。\n如果提前告诉我们,我们会为它们多准备一些毛巾。",
        "landing.slider.example6.question": "一小时的策略咨询多少钱,怎么预约?",
        "landing.slider.example6.reply": "一小时的策略咨询是90欧元,之后会附上简短的书面总结。\n本周二或周四上午我还有空档,哪天方便呢?",
        "landing.slider.example7.question": "绿色中长裙有M码吗?你们的退货政策是怎样的?",
        "landing.slider.example7.reply": "有的,绿色中长裙M码还有现货!\n14天内吊牌完好可免费退货。\n但改过尺寸的商品不支持退换。",
        "landing.slider.example8.question": "凝胶美甲多少钱,需要提前预约吗?",
        "landing.slider.example8.reply": "凝胶美甲是28欧元,大约需要45分钟。\n周末通常提前几天就订满了,但工作日一般当天就能安排。",
        "landing.slider.example9.question": "月度套餐多少钱?如果我从来没训练过也可以吗?",
        "landing.slider.example9.reply": "月度套餐是80欧元,包含8节课。\n完全可以从零基础开始,很多学员都是这样。\n第一节课是轻松的能力评估,方便教练根据您的实际水平制定计划。",
        "landing.slider.example10.question": "9月12日的婚礼还有档期吗?你们的套餐都包含什么?",
        "landing.slider.example10.reply": "9月12日档期还有空!\n标准套餐包含6小时跟拍和300多张精修照片。\n还会在同一周内提供预览画廊,让您不用等上好几个月才能看到照片。",

