function t(key) {
    const lang = TRANSLATIONS[currentLang] || TRANSLATIONS.en;
    return lang[key] || TRANSLATIONS.en[key] || key;
}

let currentLang = "en";

// Weekday/month NAMES (schedule.html's date headers) are server-rendered via Python's
// strftime, which always produces English regardless of the client-side language chosen
// here - the server has no way to know it (language is a localStorage-only choice, never
// sent to the backend). Re-formatting them client-side via Intl.DateTimeFormat, keyed off
// a raw ISO date the template also emits, fixes that without a backend round-trip. Plain
// numeric dates/times elsewhere (e.g. dashboard's "07/22/2026 at 14:30") are left alone -
// that's a format-convention choice, not a translatable word.
const DATE_FORMAT_PRESETS = {
    full: { weekday: "long", month: "short", day: "numeric", year: "numeric" },
    monthDay: { month: "short", day: "numeric" },
    monthDayYear: { month: "short", day: "numeric", year: "numeric" },
    weekdayShort: { weekday: "short" },
};
function formatLocalizedDate(isoDate, presetName) {
    const options = DATE_FORMAT_PRESETS[presetName] || DATE_FORMAT_PRESETS.full;
    const date = new Date(isoDate + "T00:00:00");
    try {
        return new Intl.DateTimeFormat(currentLang, options).format(date);
    } catch (e) {
        return new Intl.DateTimeFormat("en", options).format(date);
    }
}

function applyTranslations() {
    document.documentElement.lang = currentLang;
    document.querySelectorAll("[data-i18n]").forEach((node) => {
        node.textContent = t(node.getAttribute("data-i18n"));
    });
    document.querySelectorAll("[data-i18n-placeholder]").forEach((node) => {
        node.placeholder = t(node.getAttribute("data-i18n-placeholder"));
    });
    document.querySelectorAll("[data-i18n-date]").forEach((node) => {
        node.textContent = formatLocalizedDate(node.getAttribute("data-i18n-date"), node.getAttribute("data-i18n-date-format"));
    });
    const lang = LANGUAGES.find((l) => l.code === currentLang);
    const btn = document.getElementById("site-lang-select-btn");
    const flagEl = document.getElementById("site-lang-select-flag");
    if (flagEl && lang) flagEl.src = `/static/flags/${lang.flag}`;
    if (btn && lang) {
        btn.title = lang.name;
        btn.setAttribute("aria-label", `Change language (current: ${lang.name})`);
    }
    document.querySelectorAll(".site-lang-option-btn").forEach((row) => {
        row.classList.toggle("active", row.dataset.code === currentLang);
    });

    // The install banner (templates/base.html #mobile-install-banner) is measured for
    // --install-banner-h before this function ever runs (see the inline script there) -
    // refresh it now that its text just changed, since a translated string can wrap to a
    // different number of lines than the English default it was first measured against.
    if (typeof window.refreshInstallBannerHeight === "function") {
        window.refreshInstallBannerHeight();
    }

    // Lets listeners outside this file (e.g. the support widget in base.html, which
    // renders its greeting once from t() rather than via a data-i18n node) react to a
    // language switch without requiring a page refresh.
    document.dispatchEvent(new CustomEvent("site-language-changed", { detail: { lang: currentLang } }));
}

function setLanguage(code) {
    if (!TRANSLATIONS[code]) return;
    currentLang = code;
    try { localStorage.setItem("siteLanguage", code); } catch (e) {}
    applyTranslations();
}

// Best-effort IP geolocation so a visitor physically in, say, Serbia or Germany gets
// that language even when their OS/browser is set to English (common on shared or
// work machines). Only ever called when the visitor has no saved preference yet -
// this never overrides a language the flag picker was used to choose, on this visit
// or a past one. A short timeout keeps a slow/blocked request from ever being
// noticeable; failures (offline, ad-blocker, API down) are silently ignored and the
// synchronous browser-language guess already applied by initLanguage() stands.
function detectLanguageFromLocation() {
    if (!("fetch" in window)) return;
    const controller = ("AbortController" in window) ? new AbortController() : null;
    const timer = controller ? setTimeout(() => controller.abort(), 3000) : null;
    fetch("https://ipapi.co/json/", controller ? { signal: controller.signal } : {})
        .then((res) => res.json())
        .then((data) => {
            let saved = null;
            try { saved = localStorage.getItem("siteLanguage"); } catch (e) {}
            if (saved && TRANSLATIONS[saved]) return; // user picked one in the meantime
            const lang = COUNTRY_LANG_MAP[(data && data.country_code || "").toUpperCase()];
            if (lang && TRANSLATIONS[lang] && lang !== currentLang) setLanguage(lang);
        })
        .catch(() => {})
        .finally(() => { if (timer) clearTimeout(timer); });
}

function initLanguage() {
    let saved = null;
    try { saved = localStorage.getItem("siteLanguage"); } catch (e) {}
    if (saved && TRANSLATIONS[saved]) {
        currentLang = saved;
    } else {
        // Best-effort default from the browser's own language, same fallback logic as
        // the mobile app - falls back to English (not Serbian, unlike mobile's phone-
        // number-country guess) since the website has no equivalent "home market" signal.
        const guess = (navigator.language || "").slice(0, 2).toLowerCase();
        if (TRANSLATIONS[guess]) currentLang = guess;
        detectLanguageFromLocation();
    }
    applyTranslations();
}

function setupLanguagePicker() {
    const btn = document.getElementById("site-lang-select-btn");
    const modal = document.getElementById("site-lang-modal");
    const backdrop = document.getElementById("site-lang-modal-backdrop");
    const list = document.getElementById("site-lang-modal-list");
    if (!btn || !modal || !list) return;

    const openPicker = () => {
        modal.classList.add("open");
        btn.classList.add("active");
    };
    const closePicker = () => {
        modal.classList.remove("open");
        btn.classList.remove("active");
    };

    LANGUAGES.forEach((lang) => {
        const row = document.createElement("button");
        row.type = "button";
        row.className = "site-lang-option-btn";
        row.dataset.code = lang.code;
        const flagImg = document.createElement("img");
        flagImg.className = "site-lang-option-flag";
        flagImg.src = `/static/flags/${lang.flag}`;
        flagImg.alt = "";
        const nameSpan = document.createElement("span");
        nameSpan.className = "site-lang-option-name";
        nameSpan.textContent = lang.name;
        row.append(flagImg, nameSpan);
        row.addEventListener("click", () => {
            setLanguage(lang.code);
            closePicker();
        });
        list.appendChild(row);
    });

    btn.addEventListener("click", () => {
        if (modal.classList.contains("open")) closePicker();
        else openPicker();
    });
    backdrop.addEventListener("click", closePicker);
}

document.addEventListener("DOMContentLoaded", () => {
    setupLanguagePicker();
    initLanguage();
});

// The main nav (_nav.html) is hx-boosted - clicking Conversations/Profile/Settings/
// Subscription swaps htmx's default target (document.body's innerHTML) via AJAX instead
// of a full page load, so DOMContentLoaded (which only fires once) never re-fires for
// it. That swap replaces the picker button/modal too (they're rendered as part of every
// page's <body> via base.html, same as the content), leaving fresh DOM nodes with no
// click listeners and default English text - re-running both setup steps against
// whatever's currently in the DOM fixes both.
document.body.addEventListener("htmx:afterSwap", () => {
    setupLanguagePicker();
    applyTranslations();
});
